async function sendMentionNotices(env,actor,recipients,target) {
  if (!recipients.size) return {};
  const at = Date.now();
  const suffix = reverseTime(at) + ":" + crypto.randomUUID();
  const metadata = {
    ...target, actor: actor.username, at, title: Array.from(target.title).slice(0,80).join(""),
  };
  const writes = await Promise.allSettled([...recipients.values()].map(recipient => {
    const account = notificationScope(recipient);
    if (env.COMMUNITY_STORE) return callNotificationStore(env, account, "save", { id: suffix, notice: metadata });
    return env.POSTS.put("mention:" + account + suffix, "", { metadata, expirationTtl: NOTIFICATION_LIFETIME });
  }));
  const failed = writes.filter(write => write.status === "rejected").length;
  if (!failed) return {};
  console.error("Mention notification writes failed:", failed);
  return { mentionDeliveryFailed: true };
}

async function getReadThrough(env, user) {
  const prefix = "mention-read:" + notificationScope(user);
  const { keys } = await env.POSTS.list({ prefix, limit: 1 });
  const marker = keys[0]?.name.slice(prefix.length,prefix.length + 13);
  return /^\d{13}$/.test(marker ?? "") ? Math.max(0, NOTIFICATION_CLOCK - Number(marker)) : 0;
}

async function readInbox(env, user, minimumReadThrough = 0) {
  const account = notificationScope(user);
  if (env.COMMUNITY_STORE) {
    return callNotificationStore(env, account, "read", { through: minimumReadThrough });
  }
  try {
    const [{ keys }, savedReadThrough] = await Promise.all([
      env.POSTS.list({ prefix: "mention:" + account, limit: INBOX_LIMIT + 1 }),
      getReadThrough(env,user),
    ]);
    const readThrough = Math.max(savedReadThrough,minimumReadThrough);
    const notices = keys.map(key => key.metadata).filter(validInboxNotice);
    const unread = notices.filter(notice => notice.at > readThrough).length;
    return { entries: notices.slice(0,INBOX_LIMIT), readThrough, unread: Math.min(unread,INBOX_LIMIT), more: unread > INBOX_LIMIT };
  } catch (error) {
    console.warn("Notification history unavailable:",error?.message);
    return { entries: [], readThrough: minimumReadThrough, unread: 0, more: false, legacyUnavailable: true };
  }
}

async function markInboxRead(env,user,through) {
  const account = notificationScope(user);
  if (env.COMMUNITY_STORE) {
    await callNotificationStore(env, account, "mark", { through });
    return;
  }
  if (through <= await getReadThrough(env,user)) return;
  await env.POSTS.put("mention-read:" + account + reverseTime(through) + ":" + crypto.randomUUID(),"",{
    expirationTtl: NOTIFICATION_LIFETIME,
  });
}
